import {
	dedupeImports,
	renderTsSourceFile,
	type TsExpression,
	type TsImportSpec,
	type TsSourceFile,
} from "@fcalell/cli/ast";
import type {
	CodegenEntryPayload,
	CodegenExpoConfigPayload,
	CodegenMetroPayload,
	ExpoConfigPlugin,
	MetroRequireSpec,
} from "../types.ts";

export const GENERATED_LINE =
	"// Generated by @fcalell/plugin-expo — do not edit.";
const CONFIG_BANNER = `${GENERATED_LINE}\n// Configure native behaviour through stack.config.ts, not this file.`;

// Render a JSON-serializable value as a JS literal at the given indent. JSON's
// output is valid JS, so this is just `JSON.stringify` with the continuation
// lines re-indented to sit inside the surrounding literal.
function renderJsLiteral(value: unknown, indent: string): string {
	const json = JSON.stringify(value, null, "\t");
	return json.replace(/\n/g, `\n${indent}`);
}

// ── metro.config.cjs (CommonJS) ────────────────────────────────────
// Emitted as .cjs: docs/architecture/plugins/expo.md, "Config files are .cjs".

const BASE_METRO_REQUIRE: MetroRequireSpec = {
	names: ["getDefaultConfig"],
	module: "expo/metro-config",
};

// The `virtual:` modules plugin-api generates, by the file under `.stack/`.
const VIRTUAL_MODULES: Record<string, string> = {
	"virtual:stack-procedure": ".stack/procedure.ts",
	"virtual:stack-schema": ".stack/schema.ts",
};

export function aggregateMetroConfig(payload: CodegenMetroPayload): string {
	const requires = dedupeMetroRequires([
		BASE_METRO_REQUIRE,
		...payload.requires,
	]);
	const wrappers = [...payload.wrappers].sort((a, b) => {
		const order = (a.order ?? 0) - (b.order ?? 0);
		return order !== 0 ? order : a.callee.localeCompare(b.callee);
	});

	const lines: string[] = [CONFIG_BANNER, ""];

	for (const req of requires) {
		lines.push(
			`const { ${req.names.join(", ")} } = require(${JSON.stringify(req.module)});`,
		);
	}
	lines.push("");

	// This file is generated into `.stack/`, so `__dirname` is the consumer's
	// `.stack/` dir — NOT the project root. Metro resolves modules and the
	// entry's `require.context` app dir from `projectRoot`, so it must be the
	// real root (one level up); otherwise `../src/app` sits outside the project
	// and won't bundle. uniwind's `cssEntryFile`/`dtsFile` are likewise
	// projectRoot-relative and point back into `.stack/`.
	lines.push('const path = require("node:path");');
	lines.push('const projectRoot = path.resolve(__dirname, "..");');
	lines.push("");

	const binding = wrappers.length > 0 ? "let" : "const";
	lines.push(`${binding} config = getDefaultConfig(projectRoot);`);
	for (const wrapper of wrappers) {
		const args =
			wrapper.options === undefined
				? "config"
				: `config, ${renderJsLiteral(wrapper.options, "")}`;
		lines.push(`config = ${wrapper.callee}(${args});`);
	}
	lines.push("");
	// Metro resolves virtual: names through resolveRequest: docs/architecture/plugins/expo.md, "Metro resolution".
	lines.push("const virtualModules = {");
	for (const [name, file] of Object.entries(VIRTUAL_MODULES)) {
		lines.push(`	${JSON.stringify(name)}: ${JSON.stringify(file)},`);
	}
	lines.push("};");
	lines.push("const resolveRequest = config.resolver.resolveRequest;");
	lines.push(
		"config.resolver.resolveRequest = (context, moduleName, platform) => {",
	);
	lines.push("\tconst file = virtualModules[moduleName];");
	lines.push(
		'\tif (file) return { type: "sourceFile", filePath: path.join(projectRoot, file) };',
	);
	lines.push(
		"\treturn (resolveRequest ?? context.resolveRequest)(context, moduleName, platform);",
	);
	lines.push("};");
	lines.push("");
	lines.push("module.exports = config;");

	return lines.join("\n");
}

// Dedupe by module, merging the destructured names so two contributors asking
// for different exports of the same module collapse into one require line.
function dedupeMetroRequires(specs: MetroRequireSpec[]): MetroRequireSpec[] {
	const byModule = new Map<string, Set<string>>();
	const order: string[] = [];
	for (const spec of specs) {
		let names = byModule.get(spec.module);
		if (!names) {
			names = new Set();
			byModule.set(spec.module, names);
			order.push(spec.module);
		}
		for (const name of spec.names) names.add(name);
	}
	order.sort((a, b) => a.localeCompare(b));
	return order.map((module) => ({
		module,
		names: [...(byModule.get(module) ?? [])].sort((a, b) => a.localeCompare(b)),
	}));
}

// ── app.config.cjs (CommonJS) ──────────────────────────────────────
// Emitted as .cjs, with a JSDoc @type: docs/architecture/plugins/expo.md, "Config files are .cjs".

function renderConfigPlugin(plugin: ExpoConfigPlugin): string {
	const value =
		plugin.options === undefined ? plugin.name : [plugin.name, plugin.options];
	return renderJsLiteral(value, "\t\t");
}

export function aggregateExpoConfig(payload: CodegenExpoConfigPayload): string {
	const props: string[] = [
		`\tname: ${JSON.stringify(payload.name)},`,
		`\tslug: ${JSON.stringify(payload.slug)},`,
		`\tscheme: ${JSON.stringify(payload.scheme)},`,
		`\tversion: "1.0.0",`,
		`\torientation: "portrait",`,
		// "automatic" lets the app follow the OS light or dark setting, which the
		// design system's light and dark themes read.
		`\tuserInterfaceStyle: "automatic",`,
		`\tios: {`,
		`\t\tsupportsTablet: false,`,
		`\t\tbundleIdentifier: ${JSON.stringify(payload.bundleIdentifier)},`,
		`\t},`,
		`\tandroid: {`,
		`\t\tpackage: ${JSON.stringify(payload.androidPackage)},`,
		`\t},`,
	];

	const pluginLines = payload.plugins.map(
		(p) => `\t\t${renderConfigPlugin(p)},`,
	);
	props.push(`\tplugins: [`, ...pluginLines, `\t],`);

	const body = [
		CONFIG_BANNER,
		"",
		'/** @type {import("expo/config").ExpoConfig} */',
		"const config = {",
		...props,
		"};",
		"",
		"module.exports = config;",
	].join("\n");

	return body;
}

// ── entry.tsx ──────────────────────────────────────────────────────

function requireContextCall(appContextPath: string): TsExpression {
	return {
		kind: "call",
		callee: {
			kind: "member",
			object: { kind: "identifier", name: "require" },
			property: "context",
		},
		args: [{ kind: "string", value: appContextPath }],
	};
}

// Render `.stack/entry.tsx`. Composes contributed providers (outermost =
// lowest `order`) around the expo-router
// root. Returns null when routing is disabled — there is no root to mount.
export function aggregateEntry(payload: CodegenEntryPayload): string | null {
	if (payload.appContextPath === null) return null;

	// Android draws the status bar's icons light unless told otherwise, so a
	// light ground hides them. `auto` reads `useColorScheme()`, which follows
	// the OS setting and the scheme the theme sets through `Appearance`.
	const root: TsExpression = {
		kind: "jsx",
		tag: "Fragment",
		props: [],
		children: [
			{
				kind: "jsx",
				tag: "ExpoRoot",
				props: [
					{
						name: "context",
						value: requireContextCall(payload.appContextPath),
					},
				],
				children: [],
				selfClosing: true,
			},
			{
				kind: "jsx",
				tag: "StatusBar",
				props: [{ name: "style", value: { kind: "string", value: "auto" } }],
				children: [],
				selfClosing: true,
			},
		],
	};

	// Providers arrive pre-sorted ascending by `order` from the owning list
	// slot. Wrap from the inside out so the first provider is the outermost.
	let inner = root;
	for (let i = payload.providers.length - 1; i >= 0; i--) {
		const spec = payload.providers[i];
		if (!spec) continue;
		const children: TsExpression[] =
			spec.siblings && spec.siblings.length > 0
				? [inner, ...spec.siblings]
				: [inner];
		inner = {
			kind: "jsx",
			tag: spec.wrap.identifier,
			props: (spec.wrap.props ?? []).map((p) => ({
				name: p.name,
				value: p.value,
			})),
			children,
		};
	}

	const imports: TsImportSpec[] = dedupeImports([
		{ source: "expo", named: ["registerRootComponent"] },
		{ source: "expo-router", named: ["ExpoRoot"] },
		{ source: "expo-status-bar", named: ["StatusBar"] },
		{ source: "react", named: ["Fragment"] },
		...payload.imports,
		...payload.providers.flatMap((p) => p.imports),
	]);

	const spec: TsSourceFile = {
		imports,
		statements: [
			{
				kind: "const",
				name: "App",
				exported: true,
				value: { kind: "arrow", params: [], body: inner },
			},
			{
				kind: "expression",
				value: {
					kind: "call",
					callee: { kind: "identifier", name: "registerRootComponent" },
					args: [{ kind: "identifier", name: "App" }],
				},
			},
		],
	};

	return renderTsSourceFile(spec);
}
